	{
		// Spawn clutter volume for Environment_Clutter_Graph
		{
			UObject* GraphAsset = StaticLoadObject(UObject::StaticClass(), nullptr, TEXT("/Game/ProceduralGenerated/PCG/UPCG_Graph_Environment_Clutter_Graph.UPCG_Graph_Environment_Clutter_Graph"));
			if (GraphAsset)
			{
				PcgVolumeManager->SpawnPCGVolumeForGraph(TEXT("/Game/ProceduralGenerated/PCG/UPCG_Graph_Environment_Clutter_Graph.UPCG_Graph_Environment_Clutter_Graph"), FVector(0.f, 0.f, 100.f), FVector(50000.f, 50000.f, 10000.f), NAME_None);
				UE_LOG(LogTemp, Log, TEXT("GAMEMODE: PCG clutter volume spawned for Environment_Clutter_Graph"));
			}
			else
			{
				UE_LOG(LogTemp, Warning, TEXT("PCG graph asset not found: %s. Skipping PCG generation."), TEXT("/Game/ProceduralGenerated/PCG/UPCG_Graph_Environment_Clutter_Graph.UPCG_Graph_Environment_Clutter_Graph"));
			}
		}

		// Spawn planet surface volume for Planet_Surface_Generation
		{
			UObject* GraphAsset = StaticLoadObject(UObject::StaticClass(), nullptr, TEXT("/Game/ProceduralGenerated/PCG/UPCG_Graph_Planet_Surface_Generation.UPCG_Graph_Planet_Surface_Generation"));
			if (GraphAsset)
			{
				PcgVolumeManager->SpawnPCGVolumeForGraph(TEXT("/Game/ProceduralGenerated/PCG/UPCG_Graph_Planet_Surface_Generation.UPCG_Graph_Planet_Surface_Generation"), FVector(100000.f, 0.f, 0.f), FVector(50000.f, 50000.f, 10000.f), NAME_None);
				UE_LOG(LogTemp, Log, TEXT("GAMEMODE: PCG planet volume spawned for Planet_Surface_Generation"));
			}
			else
			{
				UE_LOG(LogTemp, Warning, TEXT("PCG graph asset not found: %s. Skipping PCG generation."), TEXT("/Game/ProceduralGenerated/PCG/UPCG_Graph_Planet_Surface_Generation.UPCG_Graph_Planet_Surface_Generation"));
			}
		}

	}
