			if (SpawnedStation0)
		{
			UE_LOG(LogTemp, Log, TEXT("SPAWNED: Station Orbital_Hub_7 at {%s} with visible mesh"), *SpawnedStation0->GetActorLocation().ToString());
		}
		else
		{
			UE_LOG(LogTemp, Error, TEXT("SPAWN FAILED: Station Orbital_Hub_7"));
		}
	}
