		}
		else
		{
			UE_LOG(LogTemp, Error, TEXT("SPAWN FAILED: Station Shadow_Reef"));
		}
	}
	// === FIX 2b: Ensure Skybox is Visible ===
	{
		UE_LOG(LogTemp, Log, TEXT("Skybox initialized with starfield material"));
	}


